<?php ob_start(); ?><h1>Users</h1><table><tr><th>Name</th><th>Path</th><th>Sites</th><th>Findings</th><th>Last scan</th><th>Actions</th></tr><?php foreach($users as $u): ?><tr><td><?= e($u['name']) ?></td><td><code><?= e($u['base_path']) ?></code></td><td><?= e($u['sites_count']) ?></td><td><?= e($u['findings_count']) ?></td><td><?= e($u['last_scan_at']) ?></td><td><form class="scan-form" method="post" action="/scan/start"><input type="hidden" name="scope" value="user"><input type="hidden" name="value" value="<?= e($u['name']) ?>"><select class="input" name="profile"><?php foreach(['fast','standard','deep'] as $p): ?><option value="<?= $p ?>"><?= $p ?></option><?php endforeach ?></select><button class="btn small">Scan this user</button></form></td></tr><?php endforeach ?></table><?php $content=ob_get_clean(); include base_path('resources/views/layouts/app.php'); ?>
